<template><Head><title>{{ count ? 'Инвентаризация №' + count.id : 'Новая инвентаризация' }}</title></Head><div class="mi-page"><div class="content-header"><div class="container-fluid"><h5 class="m-0">{{ count ? 'Инвентаризация №' + count.id : 'Новая инвентаризация' }}</h5></div></div><div class="content"><div class="container-fluid"><div class="card card-primary"><form @submit.prevent="submit"><div class="card-body"><div class="row align-items-end mb-3" v-if="!completed"><div class="col-md-6 mb-2"><label>Добавить материал</label><select v-model.number="selectedId" class="form-control"><option :value="null">Выберите материал</option><option v-for="material in availableMaterials" :value="material.id">{{ material.name }} ({{ material.unit }})</option></select></div><div class="col-md-2 mb-2"><button type="button" class="btn btn-outline-primary btn-block" :disabled="!selectedId" @click="addItem">Добавить</button></div></div><div class="form-group"><label>Комментарий</label><textarea v-model="form.comment" class="form-control" :disabled="completed"></textarea></div><div class="table-responsive mi-table-wrap"><table class="table table-bordered mi-mobile-table mi-form-table"><thead><tr><th>Материал</th><th>Учетное количество</th><th>Фактическое количество</th><th>Разница</th><th v-if="!completed"></th></tr></thead><tbody><tr v-for="(item, index) in form.items"><td data-label="Материал">{{ item.nomenclature }} <small>{{ item.unit }}</small></td><td data-label="Учетное">{{ item.book_quantity }}</td><td data-label="Фактическое"><input v-if="!completed" v-model="item.actual_quantity" type="number" step="0.000001" min="0" class="form-control"><span v-else>{{ item.actual_quantity }}</span></td><td data-label="Разница">{{ difference(item) }}</td><td v-if="!completed" data-label=""><button type="button" class="btn btn-outline-danger btn-sm" @click="form.items.splice(index, 1)">Удалить</button></td></tr><tr v-if="!form.items.length"><td colspan="5" class="text-center text-muted">Добавьте материалы для пересчета.</td></tr></tbody></table></div></div><div class="card-footer mi-actions"><button v-if="!completed" class="btn btn-primary" :disabled="form.processing">{{ count ? 'Сохранить' : 'Создать черновик' }}</button><button v-if="count && !completed" type="button" class="btn btn-success" @click="complete">Провести</button><Link :href="route('inventory-counts.index')" class="btn btn-default">К списку</Link></div></form></div></div></div></div></template>
<script>import {Head, Link, useForm} from '@inertiajs/inertia-vue3'; export default {components: {Head, Link}, props: ['count', 'materials', 'errors'], data() { return {selectedId: null, form: useForm({comment: this.count?.comment || '', items: (this.count?.items || []).map(item => ({...item}))})} }, computed: {completed() { return this.count?.status === 'completed' }, availableMaterials() { return this.materials.filter(material => !this.form.items.some(item => item.nomenclature_id === material.id)) }}, methods: {addItem() { const material = this.materials.find(item => item.id === this.selectedId); if (!material) return; this.form.items.push({nomenclature_id: material.id, nomenclature: material.name, unit: material.unit, book_quantity: 'Будет зафиксирован при сохранении', actual_quantity: 0}); this.selectedId = null }, difference(item) { if (item.book_quantity === 'Будет зафиксирован при сохранении') return '—'; return (Number(item.actual_quantity) - Number(item.book_quantity)).toFixed(6) }, submit() { this.count ? this.form.put(route('inventory-counts.update', this.count.id)) : this.form.post(route('inventory-counts.store')) }, complete() { if (confirm('Провести инвентаризацию? После проведения изменить её нельзя.')) this.$inertia.post(route('inventory-counts.complete', this.count.id)) }}};</script>
